<section id="w1" class="w1-root" aria-labelledby="w1-title">
<style>
#w1, #w1 * { box-sizing: border-box; }
#w1 { font-family: Georgia, "Times New Roman", serif; color: #2b2b2b; background: #fffaf7; width: 100%; overflow-x: hidden; }
#w1 .w1-header { background: #f9e3e6; text-align: center; padding: 40px 16px 32px; border-bottom: 1px solid #efc9cf; }
#w1 .w1-header h1 { margin: 0 0 8px; font-size: 2.2rem; line-height: 1.15; color: #8a2f45; overflow-wrap: anywhere; }
#w1 .w1-header p { margin: 0; font-size: 1.1rem; color: #5a4046; }
#w1 .w1-wrap { max-width: 1100px; margin: 0 auto; padding: 32px 16px; }
#w1 .w1-wrap h2 { margin: 0 0 20px; font-size: 1.5rem; color: #8a2f45; text-align: center; }
#w1 .w1-grid { list-style: none; margin: 0; padding: 0; display: grid; gap: 20px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 200px), 1fr)); }
#w1 .w1-card { background: #fff; border: 1px solid #ecd9dc; border-radius: 12px; overflow: hidden; display: flex; flex-direction: column; min-width: 0; }
#w1 .w1-photo { aspect-ratio: 4 / 3; width: 100%; background: #f6eef0; border-bottom: 2px dashed #d7b3ba; display: flex; align-items: center; justify-content: center; color: #8d6f76; font-size: 0.9rem; text-align: center; padding: 8px; }
#w1 .w1-body { padding: 14px 16px 18px; }
#w1 .w1-body h3 { margin: 0 0 6px; font-size: 1.1rem; overflow-wrap: anywhere; }
#w1 .w1-price { margin: 0; font-size: 1.25rem; font-weight: bold; color: #8a2f45; }
@media (min-width: 900px) {
  #w1 .w1-header { padding: 56px 24px 44px; }
  #w1 .w1-header h1 { font-size: 3rem; }
}
</style>

<header class="w1-header">
  <h1 id="w1-title">Petal &amp; Stem</h1>
  <p>A flower shop in Jaipur</p>
</header>

<div class="w1-wrap">
  <h2>Our bouquets</h2>
  <ul class="w1-grid">
    <li class="w1-card">
      <div class="w1-photo" role="img" aria-label="Photo of Red rose dozen to be added">Photo coming soon</div>
      <div class="w1-body">
        <h3>Red rose dozen</h3>
        <p class="w1-price">₹899</p>
      </div>
    </li>
    <li class="w1-card">
      <div class="w1-photo" role="img" aria-label="Photo of Sunflower bunch to be added">Photo coming soon</div>
      <div class="w1-body">
        <h3>Sunflower bunch</h3>
        <p class="w1-price">₹699</p>
      </div>
    </li>
    <li class="w1-card">
      <div class="w1-photo" role="img" aria-label="Photo of Mixed seasonal to be added">Photo coming soon</div>
      <div class="w1-body">
        <h3>Mixed seasonal</h3>
        <p class="w1-price">₹999</p>
      </div>
    </li>
    <li class="w1-card">
      <div class="w1-photo" role="img" aria-label="Photo of White lilies to be added">Photo coming soon</div>
      <div class="w1-body">
        <h3>White lilies</h3>
        <p class="w1-price">₹1,199</p>
      </div>
    </li>
    <li class="w1-card">
      <div class="w1-photo" role="img" aria-label="Photo of Orchid box to be added">Photo coming soon</div>
      <div class="w1-body">
        <h3>Orchid box</h3>
        <p class="w1-price">₹1,499</p>
      </div>
    </li>
  </ul>
</div>
</section>
<!-- J2:W-1 end -->
<!-- J2:W-2 start (owner W-2) -->
<section id="w2" class="w2-root" aria-labelledby="w2-title">
<style>
#w2, #w2 * { box-sizing: border-box; }
#w2 { font-family: Georgia, "Times New Roman", serif; color: #2b2b2b; background: #fff; width: 100%; overflow-x: hidden; border-top: 1px solid #ecd9dc; }
#w2 .w2-wrap { max-width: 640px; margin: 0 auto; padding: 32px 16px 40px; }
#w2 h2 { margin: 0 0 8px; font-size: 1.5rem; color: #8a2f45; text-align: center; }
#w2 .w2-intro { margin: 0 0 20px; text-align: center; color: #5a4046; }
#w2 .w2-terms { background: #f9e3e6; border: 1px solid #efc9cf; border-radius: 12px; padding: 14px 16px; margin: 0 0 24px; color: #5a4046; overflow-wrap: anywhere; }
#w2 .w2-terms p { margin: 0; }
#w2 form { display: block; }
#w2 .w2-field { margin: 0 0 16px; }
#w2 label { display: block; margin: 0 0 6px; font-weight: bold; color: #2b2b2b; }
#w2 select, #w2 input, #w2 textarea { display: block; width: 100%; max-width: 100%; font: inherit; font-size: 16px; padding: 10px 12px; border: 1px solid #d7b3ba; border-radius: 8px; background: #fff; color: #2b2b2b; }
#w2 textarea { min-height: 96px; resize: vertical; }
#w2 select:focus, #w2 input:focus, #w2 textarea:focus, #w2 button:focus-visible, #w2 a:focus-visible { outline: 3px solid #c9708a; outline-offset: 1px; }
#w2 .w2-invalid { border-color: #b3261e; background: #fff6f5; }
#w2 .w2-error { margin: 6px 0 0; color: #b3261e; font-size: 0.9rem; min-height: 0; }
#w2 .w2-error:empty { display: none; }
#w2 button { width: 100%; font: inherit; font-size: 1.05rem; font-weight: bold; padding: 14px 16px; border: 0; border-radius: 10px; background: #8a2f45; color: #fff; cursor: pointer; }
#w2 button:hover { background: #722639; }
#w2 .w2-status { margin: 16px 0 0; text-align: center; color: #5a4046; overflow-wrap: anywhere; }
#w2 .w2-status:empty { display: none; }
#w2 .w2-status a { color: #8a2f45; font-weight: bold; }
@media (min-width: 900px) {
  #w2 .w2-wrap { padding: 48px 24px 56px; }
  #w2 h2 { font-size: 1.8rem; }
}
</style>

<div class="w2-wrap" id="order">
  <h2 id="w2-title">Order a bouquet for delivery</h2>
  <p class="w2-intro">Fill in the form and your order opens as a WhatsApp message to the shop.</p>

  <div class="w2-terms">
    <p>Delivery: same day delivery inside Jaipur for orders placed before 4pm, ₹99 delivery charge, pay on delivery.</p>
  </div>

  <form id="w2-form" novalidate>
    <div class="w2-field">
      <label for="w2-bouquet">Bouquet</label>
      <select id="w2-bouquet" name="bouquet" required aria-describedby="w2-err-bouquet">
        <option value="">Choose a bouquet</option>
        <option value="Red rose dozen">Red rose dozen (₹899)</option>
        <option value="Sunflower bunch">Sunflower bunch (₹699)</option>
        <option value="Mixed seasonal">Mixed seasonal (₹999)</option>
        <option value="White lilies">White lilies (₹1,199)</option>
        <option value="Orchid box">Orchid box (₹1,499)</option>
      </select>
      <p class="w2-error" id="w2-err-bouquet" aria-live="polite"></p>
    </div>

    <div class="w2-field">
      <label for="w2-name">Your name</label>
      <input type="text" id="w2-name" name="name" autocomplete="name" required aria-describedby="w2-err-name">
      <p class="w2-error" id="w2-err-name" aria-live="polite"></p>
    </div>

    <div class="w2-field">
      <label for="w2-phone">Your phone number</label>
      <input type="tel" id="w2-phone" name="phone" inputmode="tel" autocomplete="tel" required aria-describedby="w2-err-phone">
      <p class="w2-error" id="w2-err-phone" aria-live="polite"></p>
    </div>

    <div class="w2-field">
      <label for="w2-address">Delivery address</label>
      <textarea id="w2-address" name="address" autocomplete="street-address" required aria-describedby="w2-err-address"></textarea>
      <p class="w2-error" id="w2-err-address" aria-live="polite"></p>
    </div>

    <button type="submit">Send order on WhatsApp</button>
    <p class="w2-status" id="w2-status" aria-live="polite"></p>
  </form>
</div>

<script>
(function () {
  var form = document.getElementById("w2-form");
  if (!form) { return; }
  var status = document.getElementById("w2-status");
  var WA_NUMBER = "919829011223";
  var fields = [
    { id: "w2-bouquet", err: "w2-err-bouquet", msg: "Please choose a bouquet." },
    { id: "w2-name", err: "w2-err-name", msg: "Please enter your name." },
    { id: "w2-phone", err: "w2-err-phone", msg: "Please enter your phone number." },
    { id: "w2-address", err: "w2-err-address", msg: "Please enter the delivery address." }
  ];

  function clearErrors() {
    fields.forEach(function (f) {
      var el = document.getElementById(f.id);
      el.classList.remove("w2-invalid");
      el.removeAttribute("aria-invalid");
      document.getElementById(f.err).textContent = "";
    });
    status.textContent = "";
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    clearErrors();

    var firstBad = null;
    var values = {};
    fields.forEach(function (f) {
      var el = document.getElementById(f.id);
      var v = (el.value || "").trim();
      values[f.id] = v;
      if (!v) {
        el.classList.add("w2-invalid");
        el.setAttribute("aria-invalid", "true");
        document.getElementById(f.err).textContent = f.msg;
        if (!firstBad) { firstBad = el; }
      }
    });
    if (firstBad) {
      firstBad.focus();
      return;
    }

    var text = "Hello Petal & Stem, I would like to order a bouquet for delivery.\n" +
      "Bouquet: " + values["w2-bouquet"] + "\n" +
      "Name: " + values["w2-name"] + "\n" +
      "Phone: " + values["w2-phone"] + "\n" +
      "Address: " + values["w2-address"] + "\n" +
      "Payment: on delivery";
    var url = "https://wa.me/" + WA_NUMBER + "?text=" + encodeURIComponent(text);

    var win = null;
    try { win = window.open(url, "_blank"); } catch (err) { win = null; }
    if (!win) {
      window.location.href = url;
      return;
    }
    status.innerHTML = "";
    var msg = document.createTextNode("WhatsApp should have opened with your order. If it did not, ");
    var link = document.createElement("a");
    link.href = url;
    link.target = "_blank";
    link.rel = "noopener";
    link.textContent = "tap here to open it";
    status.appendChild(msg);
    status.appendChild(link);
    status.appendChild(document.createTextNode("."));
  });

  fields.forEach(function (f) {
    var el = document.getElementById(f.id);
    var handler = function () {
      if ((el.value || "").trim()) {
        el.classList.remove("w2-invalid");
        el.removeAttribute("aria-invalid");
        document.getElementById(f.err).textContent = "";
      }
    };
    el.addEventListener("input", handler);
    el.addEventListener("change", handler);
  });
})();
</script>
</section>
<!-- J2:W-2 end -->
<!-- J2:W-3 start (owner W-3) -->
<section id="w3" class="w3-root" aria-labelledby="w3-title">
<style>
#w3, #w3 * { box-sizing: border-box; }
#w3 { font-family: Georgia, "Times New Roman", serif; color: #2b2b2b; background: #fffaf7; width: 100%; overflow-x: hidden; border-top: 1px solid #ecd9dc; }
#w3 .w3-wrap { max-width: 1100px; margin: 0 auto; padding: 32px 16px 40px; }
#w3 h2 { margin: 0 0 20px; font-size: 1.5rem; color: #8a2f45; text-align: center; }
#w3 .w3-grid { display: grid; gap: 20px; grid-template-columns: 1fr; }
#w3 .w3-card { background: #fff; border: 1px solid #ecd9dc; border-radius: 12px; padding: 18px 16px; min-width: 0; overflow-wrap: anywhere; }
#w3 .w3-card h3 { margin: 0 0 10px; font-size: 1.1rem; color: #8a2f45; }
#w3 .w3-card p { margin: 0 0 8px; line-height: 1.5; }
#w3 .w3-card p:last-child { margin-bottom: 0; }
#w3 .w3-closed { color: #5a4046; }
#w3 a { color: #8a2f45; font-weight: bold; }
#w3 .w3-btn { display: inline-block; margin-top: 8px; padding: 12px 16px; border-radius: 10px; background: #8a2f45; color: #fff; text-decoration: none; font-weight: bold; }
#w3 .w3-btn:hover { background: #722639; }
#w3 a:focus-visible { outline: 3px solid #c9708a; outline-offset: 2px; }
@media (min-width: 900px) {
  #w3 .w3-wrap { padding: 48px 24px 56px; }
  #w3 h2 { font-size: 1.8rem; }
  #w3 .w3-grid { grid-template-columns: repeat(3, 1fr); }
}
</style>

<div class="w3-wrap" id="visit">
  <h2 id="w3-title">Visit Petal &amp; Stem in Jaipur</h2>
  <div class="w3-grid">
    <div class="w3-card">
      <h3>Opening hours</h3>
      <p>9am to 8pm, Monday to Saturday</p>
      <p class="w3-closed">Closed on Sunday</p>
    </div>
    <div class="w3-card">
      <h3>Address</h3>
      <p>12 MI Road, near Panch Batti, Jaipur 302001</p>
      <a class="w3-btn" href="https://www.google.com/maps/search/?api=1&amp;query=12+MI+Road+near+Panch+Batti+Jaipur+302001" target="_blank" rel="noopener">Open in Google Maps</a>
    </div>
    <div class="w3-card">
      <h3>Phone</h3>
      <p><a href="tel:+911414005566">+91 141 400 5566</a></p>
      <p>Tap the number to call the shop.</p>
    </div>
  </div>
</div>
</section>
<!-- J2:W-3 end -->
</body>
</html>
